#include <stdlib.h>
#include <stdbool.h>

#define MAX_VARS 676

int var_to_id(char c1, char c2) {
    return (c1 - 'a') * 26 + (c2 - 'a');
}

void id_to_var(int id, char *buf) {
    buf[0] = (char)('a' + id / 26);
    buf[1] = (char)('a' + id % 26);
    buf[2] = '\0';
}

