                if (known[id]) {
                    known_sum += val[id];
                } else {
                    if (unknown_id == -1) {
                        unknown_id = id;
                        count_unknown = 1;
                    } else if (unknown_id == id) {
                        count_unknown++;
                    } else {
                        multiple_unknown_types = true;
